import os
import re
from decimal import Decimal, InvalidOperation
from datetime import datetime
from PIL import Image, ImageOps
import pytesseract
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

KEYWORD_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSIONS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED",
]

ALLOW_WITH_EXCLUSIONS = [
    "TOTAL SALES",
    "TOTAL RM INCLUDING",
    "TOTAL INCLUDING",
    "TOTAL AFTER ADJ",
    "TOTAL ROUNDED",
]

_O_TO_0_RE = re.compile(r'(?<=\d)O|O(?=\d)|(?<=\.)O|O(?=\.)', re.IGNORECASE)


def _normalize_numeric_context(s: str) -> str:
    s = _O_TO_0_RE.sub('0', s)
    s = re.sub(r'\s*\.\s*', '.', s)
    # Handle comma as decimal when no dot
    s = re.sub(r'(\d),(\d{2})(?!\d)', r'\1.\2', s)
    # Remove thousand separators
    s = re.sub(r'(\d),(\d{3})', r'\1\2', s)
    # Convert spaced decimals like '538 00' -> '538.00'
    s = re.sub(r'(\d)\s+(\d{2})(?!\d)', r'\1.\2', s)
    return s


def extract_amount(line: str):
    if not line:
        return None
    s = _normalize_numeric_context(line)
    s = s.replace('RM', ' ')
    # Prefer decimal amounts
    matches = re.findall(r'\d{1,3}(?:\d{3})*(?:\.\d{1,2})|\d+\.\d{1,2}', s)
    val = None
    if matches:
        val = matches[-1]
    else:
        # Fallback to integer if no decimal present
        matches = re.findall(r'\d+', s)
        if matches:
            val = matches[-1]
    if not val:
        return None
    try:
        dec = Decimal(val)
    except InvalidOperation:
        return None
    return f"{dec:.2f}"


def find_total(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    up_lines = [ln.upper() for ln in lines]
    for group in KEYWORD_GROUPS:
        for i, up in enumerate(up_lines):
            if any(kw in up for kw in group):
                has_excl = any(excl in up for excl in EXCLUSIONS)
                if has_excl and not any(allow in up for allow in ALLOW_WITH_EXCLUSIONS):
                    continue
                amt = extract_amount(lines[i])
                if amt is None and i + 1 < len(lines):
                    amt = extract_amount(lines[i + 1])
                if amt is not None:
                    return amt
    return None


def _fix_month_component(mo: int) -> int:
    if 1 <= mo <= 12:
        return mo
    # If OCR produced e.g. 62 for 02, 68 for 08
    if 10 < mo < 100:
        mo2 = mo % 10
        if 1 <= mo2 <= 12:
            return mo2
    return mo


def find_date(text: str):
    t = _normalize_numeric_context(text)
    patterns = [
        r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})',
        r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})',
        r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{2})',
    ]
    for pat in patterns:
        for m in re.finditer(pat, t):
            g1, g2, g3 = m.groups()
            try:
                if pat == patterns[0]:
                    y, mo, d = int(g1), int(g2), int(g3)
                else:
                    a, b = int(g1), int(g2)
                    if pat == patterns[1]:
                        y = int(g3)
                    else:
                        yy = int(g3)
                        y = 2000 + yy
                    if a > 12 and b <= 12:
                        d, mo = a, b
                    elif b > 12 and a <= 12:
                        d, mo = b, a
                    else:
                        d, mo = a, b
                mo = _fix_month_component(mo)
                dt = datetime(y, mo, d)
            except Exception:
                continue
            return dt.date().isoformat()
    return None


def ocr_image(path: str) -> str:
    img = Image.open(path)
    img = ImageOps.grayscale(img)
    img = ImageOps.autocontrast(img)
    w, h = img.size
    if max(w, h) < 2000:
        img = img.resize((int(w * 2), int(h * 2)), Image.LANCZOS)
    return pytesseract.image_to_string(img)


def ocr_date_only(path: str) -> str:
    img = Image.open(path)
    img = ImageOps.grayscale(img)
    img = ImageOps.autocontrast(img)
    config = '--psm 6 -c tessedit_char_whitelist=0123456789/:-.'
    return pytesseract.image_to_string(img, config=config)


rows = []
files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])
for fname in files:
    path = os.path.join(IMG_DIR, fname)
    text = ocr_image(path)
    date = find_date(text)
    if date is None:
        # Try date-focused OCR
        date = find_date(ocr_date_only(path))
    total = find_total(text)
    rows.append((fname, date, total))

wb = Workbook()
ws = wb.active
ws.title = 'results'
ws.append(['filename', 'date', 'total_amount'])
for fname, date, total in rows:
    ws.append([fname, date if date is not None else None, total if total is not None else None])
wb.save(OUT_PATH)

print(f"Wrote {OUT_PATH} with {len(rows)} rows")
